def apply(stock, event):
    result = stock
    if event['kind'] == 'transfer':
        result[event['source']] -= event['amount']
        if result[event['source']] < 0:
            return {'stock': result, 'accepted': False}
    result[event['target']] += event['amount']
    return {'stock': result, 'accepted': True}
